import{_ as s,o as i,c as t,a2 as e}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"用 GitHub Actions + Pages 做数据站","description":"","frontmatter":{"title":"用 GitHub Actions + Pages 做数据站"},"headers":[],"relativePath":"md/tools/static-data.md","filePath":"md/tools/static-data.md","lastUpdated":1795424423000}'),n={name:"md/tools/static-data.md"};function l(o,a,h,p,d,r){return i(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="用-github-actions-pages-做数据站" tabindex="-1">用 GitHub Actions + Pages 做数据站 <a class="header-anchor" href="#用-github-actions-pages-做数据站" aria-label="Permalink to &quot;用 GitHub Actions + Pages 做数据站&quot;">​</a></h1><p>想要一个&quot;每天自动更新、有人访问、零成本&quot;的数据站点，GitHub Actions 加 Pages 是目前最省事的组合。它不需要服务器、不需要数据库、不需要运维，代价是有明确的边界。</p><h2 id="整体结构" tabindex="-1">整体结构 <a class="header-anchor" href="#整体结构" aria-label="Permalink to &quot;整体结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>定时触发（cron）</span></span>
<span class="line"><span>  → 拉取数据（API / 抓取）</span></span>
<span class="line"><span>  → 归一化成 JSON</span></span>
<span class="line"><span>  → 写入仓库（data/ 目录）</span></span>
<span class="line"><span>  → 提交 &amp; push</span></span>
<span class="line"><span>  → Pages 自动发布静态站</span></span></code></pre></div><p>站点是纯静态的，前端读 <code>data/xxx.json</code> 渲染。没有后端，所以也不会有注入、越权、数据库泄露这些问题。</p><h2 id="数据层设计要点" tabindex="-1">数据层设计要点 <a class="header-anchor" href="#数据层设计要点" aria-label="Permalink to &quot;数据层设计要点&quot;">​</a></h2><h3 id="_1-快照-索引-而不是只存最新" tabindex="-1">1. 快照 + 索引，而不是只存最新 <a class="header-anchor" href="#_1-快照-索引-而不是只存最新" aria-label="Permalink to &quot;1. 快照 + 索引，而不是只存最新&quot;">​</a></h3><p>只覆盖写最新一份，历史就没了。正确做法是两份：</p><ul><li><code>data/latest.json</code> —— 最新快照，供页面直接读</li><li><code>data/archive/YYYY-MM-DD.json</code> —— 按日期归档，供趋势和回溯</li></ul><p>归档文件会让仓库变大，但文本 JSON 压缩率很高，正常规模几年也就几十 MB。</p><h3 id="_2-schema-稳定比内容丰富重要" tabindex="-1">2. schema 稳定比内容丰富重要 <a class="header-anchor" href="#_2-schema-稳定比内容丰富重要" aria-label="Permalink to &quot;2. schema 稳定比内容丰富重要&quot;">​</a></h3><p>前端是按字段读的，一旦字段改了，历史归档就全部读不了。所以：</p><ul><li>字段名不要随心情改</li><li>新增字段可以，删除字段要谨慎</li><li>在 <code>data/schema.json</code> 里写清楚每个字段的含义和类型</li></ul><h3 id="_3-幂等-同一份数据不要重复提交" tabindex="-1">3. 幂等：同一份数据不要重复提交 <a class="header-anchor" href="#_3-幂等-同一份数据不要重复提交" aria-label="Permalink to &quot;3. 幂等：同一份数据不要重复提交&quot;">​</a></h3><p>定时任务最常见的问题是空转——数据没变化，还是提交一次，仓库历史被无意义的 commit 塞满。</p><p>处理方式：生成完 JSON 后先 <code>git diff</code> 检查，无变化就退出。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quiet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;无变化，跳过提交&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  exit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span></code></pre></div><h2 id="抓取侧的三个现实问题" tabindex="-1">抓取侧的三个现实问题 <a class="header-anchor" href="#抓取侧的三个现实问题" aria-label="Permalink to &quot;抓取侧的三个现实问题&quot;">​</a></h2><h3 id="失败要可观测" tabindex="-1">失败要可观测 <a class="header-anchor" href="#失败要可观测" aria-label="Permalink to &quot;失败要可观测&quot;">​</a></h3><p>外部 API 挂掉、返回结构变了、被限流，都会让任务失败。<strong>别让失败静默</strong>：任务失败时保留上一次成功的数据，同时在页面上显示数据时间戳。用户看到&quot;数据更新于 2 天前&quot;，比看到空白页或者错误数据要好。</p><h3 id="限流要提前规划" tabindex="-1">限流要提前规划 <a class="header-anchor" href="#限流要提前规划" aria-label="Permalink to &quot;限流要提前规划&quot;">​</a></h3><p>免费 API 普遍有速率限制。Actions 的定时任务每天跑几次不会触发限制，但如果一次要抓几百个条目，就要加延时和重试。对同一域名高频请求，很容易被封 IP —— Actions 的出口 IP 是共享的，被封的概率比自家服务器更高。</p><h3 id="依赖数据的许可" tabindex="-1">依赖数据的许可 <a class="header-anchor" href="#依赖数据的许可" aria-label="Permalink to &quot;依赖数据的许可&quot;">​</a></h3><p>抓别人的数据做站点，先看清楚对方 API 的使用条款。很多免费 API 明确禁止商用或者要求署名。这件事在技术上做起来没有门槛，在合规上不是。</p><h2 id="这套方案的边界" tabindex="-1">这套方案的边界 <a class="header-anchor" href="#这套方案的边界" aria-label="Permalink to &quot;这套方案的边界&quot;">​</a></h2><p><strong>适合</strong>：低频更新（每小时一次以内）、数据量中等（几 MB）、只读展示。</p><p><strong>不适合</strong>：</p><ul><li>需要秒级更新</li><li>需要用户交互（登录、写入）</li><li>数据量到几百 MB 以上（仓库会变慢，Pages 也有大小限制）</li><li>需要保密的数据（仓库公开就是公开的）</li></ul><p>一旦越过这些边界，就该上真正的服务器和数据库了。但在&quot;验证一个数据产品有没有人看&quot;的阶段，这套方案的性价比没有对手。</p>`,29)])])}const k=s(n,[["render",l]]);export{u as __pageData,k as default};
